package main

type Cache struct {
	capacity int
	ttl      int64
	store    map[string]int
}

func NewCache(capacity int, ttl int64) *Cache {
	return &Cache{capacity: capacity, ttl: ttl, store: make(map[string]int)}
}

func (c *Cache) Put(key string, value int, now int64) {
	c.store[key] = value
}

func (c *Cache) Get(key string, now int64) (int, bool) {
	v, ok := c.store[key]
	return v, ok
}

