package main

import "testing"

func TestCapacityEvictsLeastRecentlyUsed(t *testing.T) {
	c := NewCache(2, 1000)
	c.Put("a", 1, 0)
	c.Put("b", 2, 1)
	c.Get("a", 2)
	c.Put("c", 3, 3)
	if v, ok := c.Get("a", 4); !ok || v != 1 {
		t.Fatalf("expected a=1, got %v %v", v, ok)
	}
	if _, ok := c.Get("b", 4); ok {
		t.Fatalf("expected b evicted")
	}
	if v, ok := c.Get("c", 4); !ok || v != 3 {
		t.Fatalf("expected c=3, got %v %v", v, ok)
	}
}

func TestGetRefreshesRecency(t *testing.T) {
	c := NewCache(2, 1000)
	c.Put("a", 1, 0)
	c.Put("b", 2, 1)
	c.Get("a", 2)
	c.Get("b", 3)
	c.Put("c", 3, 4)
	if _, ok := c.Get("a", 5); ok {
		t.Fatalf("expected a evicted")
	}
	if v, ok := c.Get("b", 5); !ok || v != 2 {
		t.Fatalf("expected b=2, got %v %v", v, ok)
	}
}

func TestTTLExpiryIndependentOfCapacity(t *testing.T) {
	c := NewCache(5, 10)
	c.Put("a", 1, 0)
	if v, ok := c.Get("a", 9); !ok || v != 1 {
		t.Fatalf("expected a=1 at t=9")
	}
	if _, ok := c.Get("a", 10); ok {
		t.Fatalf("expected a expired at t=10")
	}
}

