package main

import "container/list"

type entry struct {
	key      string
	value    int
	storedAt int64
}

type Cache struct {
	capacity int
	ttl      int64
	order    *list.List
	index    map[string]*list.Element
}

func NewCache(capacity int, ttl int64) *Cache {
	return &Cache{capacity: capacity, ttl: ttl, order: list.New(), index: make(map[string]*list.Element)}
}

func (c *Cache) Put(key string, value int, now int64) {
	if el, ok := c.index[key]; ok {
		c.order.Remove(el)
		delete(c.index, key)
	} else if c.order.Len() >= c.capacity {
		oldest := c.order.Back()
		if oldest != nil {
			c.order.Remove(oldest)
			delete(c.index, oldest.Value.(*entry).key)
		}
	}
	el := c.order.PushFront(&entry{key: key, value: value, storedAt: now})
	c.index[key] = el
}

func (c *Cache) Get(key string, now int64) (int, bool) {
	el, ok := c.index[key]
	if !ok {
		return 0, false
	}
	e := el.Value.(*entry)
	if now-e.storedAt >= c.ttl {
		c.order.Remove(el)
		delete(c.index, key)
		return 0, false
	}
	c.order.MoveToFront(el)
	return e.value, true
}

